//! Generated by lichen: one entry per family.

use lichen_lowlevel::{ArrayItem, LowValue, Module, Program};
use lichen_utils::extend::AsEnum;
use std::ffi::c_void;

type Value = <lichen_language::program::LangProgram as Program>::Value;

use std::sync::atomic::{AtomicU64, Ordering};

use lichen_language::program::LangProgram;
use lichen_stages as stages;

/// The id the last `publish` call carried.
static PUBLISHED: AtomicU64 = AtomicU64::new(u64::MAX);

/// `len` arguments from `from`, read as `Int`, or `None` when one is not.
///
/// # Invariant
///
/// Every index in the range must answer `USize`: a call that passed a `Float`
/// where an `Int` belongs reads as absent rather than as a truncated number.
pub fn counts(
    module: &mut Module<LangProgram>,
    operand: &Value,
    from: usize,
    len: usize,
) -> Option<Vec<usize>> {
    (from..from + len)
        .map(
            |index| match AsEnum::<LowValue>::as_enum(&item(module, operand, index)?) {
                Some(LowValue::USize(number)) => Some(number),
                _ => None,
            },
        )
        .collect()
}

/// `len` arguments from `from`, read as `Float`, or `None` when one is not.
pub fn scalars(
    module: &mut Module<LangProgram>,
    operand: &Value,
    from: usize,
    len: usize,
) -> Option<Vec<f32>> {
    (from..from + len)
        .map(
            |index| match AsEnum::<LowValue>::as_enum(&item(module, operand, index)?) {
                Some(LowValue::Float(number)) => Some(number),
                _ => None,
            },
        )
        .collect()
}

/// A stage's answer as a lichen value.
pub fn id_of(id: Option<u64>) -> Value {
    match id {
        Some(id) => Value::from(LowValue::USize(id as usize)),
        None => Value::from(LowValue::Error),
    }
}

/// A stage's answer, for a stage that always has one.
pub fn id(id: u64) -> Value {
    id_of(Some(id))
}

/// What a call that could not be read answers.
///
/// # Invariant
///
/// `Error` and never a number: an id that names nothing must not read downstream
/// as a real answer.
pub fn missed() -> Value {
    Value::from(LowValue::Error)
}

/// Record `id` as the program's published answer, and hand it back.
///
/// # Invariant
///
/// A `SessionReport` carries its build behind an `Arc` the session's own cache
/// also holds, so a program value cannot be read out of one; publishing the
/// argument of an explicit call is how a host reads what a program actually
/// evaluated.
pub fn publish(published: u64) -> Value {
    PUBLISHED.store(published, Ordering::Relaxed);
    id(published)
}

/// The slab's fingerprint of the document under `id`.
#[unsafe(no_mangle)]
pub extern "C" fn lichen_whiting_fingerprint(id: u64) -> u64 {
    stages::slab::fingerprint(id)
}

/// The kind census of the document under `id`, one word per kind.
///
/// # Safety
///
/// The caller promises `out` names `len` machine words to write into.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn lichen_whiting_shape(id: u64, out: *mut u64, len: *mut usize) {
    let census: Vec<u64> = stages::slab::document(id)
        .map(|document| {
            stages::fingerprint::shape(&document)
                .into_iter()
                .map(|(_, count)| count)
                .collect()
        })
        .unwrap_or_default();
    // SAFETY: the caller promises `out` holds at least `census.len()` words.
    unsafe {
        std::ptr::copy_nonoverlapping(census.as_ptr(), out, census.len());
        *len = census.len();
    }
}

/// How many values the slab holds.
#[unsafe(no_mangle)]
pub extern "C" fn lichen_whiting_slab_len() -> u64 {
    stages::slab::len() as u64
}

/// The id the last `publish` call carried, or `u64::MAX` when none has.
#[unsafe(no_mangle)]
pub extern "C" fn lichen_whiting_published() -> u64 {
    PUBLISHED.load(Ordering::Relaxed)
}

/// Empty the slab, so a host can time a genuinely cold build.
///
/// # Safety
///
/// Every id handed out before this call is meaningless afterwards.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn lichen_whiting_reset() {
    stages::slab::reset();
}

/// The call's argument array.
pub fn arguments(operand: &Value) -> Vec<ArrayItem> {
    match AsEnum::<LowValue>::as_enum(operand) {
        // SAFETY: `array` is a live operand payload.
        Some(LowValue::Array(array)) => unsafe { array.items() }.to_vec(),
        _ => Vec::new(),
    }
}

/// Argument `index`, evaluated.
pub fn item(
    module: &mut Module<lichen_language::program::LangProgram>,
    operand: &Value,
    index: usize,
) -> Option<Value> {
    let items = arguments(operand);
    let item = items.get(index)?;
    module.evaluate_node(item.node, None)
}

const MANIFEST: &str = "lichen-link 1\nprogram lichen_language::program::LangProgram\nbuild 0.1.0+5f6b04661316\nfamily whiting_tree 0 lichen_whiting_tree\nfamily whiting_dressed 1 lichen_whiting_dressed\nfamily whiting_wood 2 lichen_whiting_wood\nfamily whiting_leaves 3 lichen_whiting_leaves\nfamily whiting_drawn 4 lichen_whiting_drawn\nfamily whiting_document 5 lichen_whiting_document\nfamily whiting_publish 6 lichen_whiting_publish\nbind tree\nbind dressed\nbind wood\nbind leaves\nbind drawn\nbind document\nbind publish\nsource\ntree = seed: Int => {r = $whiting_tree(seed); r: Int; r}\ndressed = tree: Int => envelope: Float => {r = $whiting_dressed(tree, envelope); r: Int; r}\nwood = wood: Int => stations: Int => around: Int => spacing: Float => {r = $whiting_wood(wood, stations, around, spacing); r: Int; r}\nleaves = leaves: Int => density: Float => {r = $whiting_leaves(leaves, density); r: Int; r}\ndrawn = wood: Int => leaves: Int => index: Int => {r = $whiting_drawn(wood, leaves, index); r: Int; r}\ndocument = drawn: Int => key_x: Float => key_y: Float => key_z: Float => {r = $whiting_document(drawn, key_x, key_y, key_z); r: Int; r}\npublish = published: Int => {r = $whiting_publish(published); r: Int; r}\n";

#[unsafe(no_mangle)]
pub unsafe extern "C" fn lichen_link_manifest(out: *mut *const u8, len: *mut usize) {
    unsafe {
        *out = MANIFEST.as_ptr();
        *len = MANIFEST.len()
    };
}

#[rustfmt::skip]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn lichen_whiting_tree(
    module: *mut c_void,
    operand: *const c_void,
    out: *mut c_void,
) {
    let module = unsafe { &mut *(module as *mut Module<lichen_language::program::LangProgram>) };
    let operand = unsafe { &*(operand as *const Value) };
    let result: Value = match counts(module, operand, 0, 1) {
    Some(a) => id(stages::tree(a[0] as u64)),
    None => missed(),
};
    unsafe { (out as *mut Value).write(result) };
}

